"use strict";Object.assign(SmmApp.prototype,{rpPlanText(e){if(!e)return"";const day=e=>{const a=new Date(String(e||"").replace(" ","T")+"Z");return Number.isNaN(a.getTime())?"":a.toLocaleDateString("tr-TR",{day:"numeric",month:"long",year:"numeric"})},a=`₺${Number(e.fee).toLocaleString("tr-TR")}`;switch(e.plan_status){case"trial":return e.auto_renew?`Deneme ${day(e.trial_ends_at)} tarihinde bitiyor; ${a} Jet bakiyenden alınacak.`:`Ücretsiz deneme: ${e.days_left} gün kaldı. Devam etmek için panelde "Devam et"e bas.`;case"active":return`Aktif · ${day(e.paid_until)} tarihine kadar ödendi${e.auto_renew?"":" (yenileme kapalı)"}.`;case"past_due":return`Aylık ücret alınamadı. ${day(e.grace_ends_at)} tarihine kadar Jet bakiyeni yükle.`;case"expired":return`Site askıda. ${day(e.delete_at)} tarihinde silinecek; panelden ödeyip açabilirsin.`;default:return"Ücretsiz panel."}},async renderResellerAccount(){const e=document.getElementById("bayilik-account");if(!e)return;const esc=e=>this.escapeHtml(e);if(!this.currentUser)return e.innerHTML='<div class="bp-card bp-cta">\n        <div><h2>Hemen ücretsiz başla</h2><p>Jet hesabınla giriş yap; panelin bir dakikada açılsın.</p></div>\n        <div class="bp-cta-actions">\n          <button type="button" class="btn btn-primary" data-rp-auth="register"><i class="fa-solid fa-user-plus" aria-hidden="true"></i> Ücretsiz Kayıt Ol</button>\n          <button type="button" class="btn btn-outline" data-rp-auth="login"><i class="fa-solid fa-right-to-bracket" aria-hidden="true"></i> Giriş Yap</button>\n        </div>\n      </div>',void this.rpBind(e);let a;e.innerHTML='<div class="bp-card"><p class="bp-muted">Yükleniyor…</p></div>';try{a=await API.getResellerMe()}catch(a){return void(e.innerHTML=`<div class="bp-card"><p class="bp-muted">${esc(a.message)}</p></div>`)}if(a.tenant){const t=a.tenant,n=t.panel_url||(t.address?`https://${t.address}/admin`:"");return void(e.innerHTML=`<div class="bp-card bp-mine">\n        <div class="bp-mine-head"><span class="bp-kicker"><i class="fa-solid fa-store" aria-hidden="true"></i> Bayi Panelim</span><h2>${esc(t.name)}</h2></div>\n        <dl class="bp-dl">\n          <dt>Site adresi</dt><dd>${t.address?`<a href="https://${esc(t.address)}" target="_blank" rel="noopener">${esc(t.address)}</a>`:"Adres yakında tanımlanacak"}</dd>\n          <dt>Durum</dt><dd>${esc(this.rpPlanText(t.subscription))}</dd>\n        </dl>\n        ${n?`<a class="btn btn-primary" href="${esc(n)}" target="_blank" rel="noopener"><i class="fa-solid fa-gauge-high" aria-hidden="true"></i> Yönetim Paneline Git</a>`:""}\n        <p class="bp-muted">Panele Jet kullanıcı adın ve şifrenle girersin.</p>\n      </div>`)}if(!a.applications_open)return void(e.innerHTML='<div class="bp-card"><p>Bayilik başvuruları şu anda kapalı. Kısa süre sonra yeniden açılacak.</p></div>');const t=a.base_domain||"";e.innerHTML=`<form class="bp-card bp-form" id="rp-apply-form" novalidate>\n      <h2>Panelini aç · ${esc(a.trial_days)} gün ücretsiz</h2>\n      <label>Site adı<input name="name" class="form-control" maxlength="60" placeholder="Örn: Kanka SMM" required></label>\n      <label>Adres <small>(küçük harf, rakam ve tire; 3-30 karakter)</small>\n        <span class="bp-slug"><input name="slug" class="form-control" maxlength="30" placeholder="kankasmm" autocomplete="off" spellcheck="false" required>${t?`<span>.${esc(t)}</span>`:""}</span>\n      </label>\n      <p class="bp-preview" id="rp-preview"></p>\n      <p class="bp-error" role="alert"></p>\n      <button type="submit" class="btn btn-primary"><i class="fa-solid fa-rocket" aria-hidden="true"></i> Ücretsiz Başlat</button>\n      <p class="bp-muted">Deneme süresince ücret alınmaz. Sonrasında devam edersen aylık ₺${Number(a.monthly_fee).toLocaleString("tr-TR")} Jet bakiyenden alınır.</p>\n    </form>`;const n=document.getElementById("rp-apply-form"),preview=()=>{const e=n.elements.namedItem("slug").value.trim().toLowerCase();document.getElementById("rp-preview").textContent=e&&t?`Siten: https://${e}.${t}`:""};n.elements.namedItem("name").addEventListener("input",e=>{const a=n.elements.namedItem("slug");a.dataset.touched||(a.value=e.target.value.toLocaleLowerCase("tr-TR").replace(/ı/g,"i").replace(/ğ/g,"g").replace(/ü/g,"u").replace(/ş/g,"s").replace(/ö/g,"o").replace(/ç/g,"c").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,30),preview())}),n.elements.namedItem("slug").addEventListener("input",e=>{e.target.dataset.touched="1",preview()}),n.addEventListener("submit",e=>this.rpSubmit(e))},async rpSubmit(e){e.preventDefault();const a=e.currentTarget,t=a.querySelector(".bp-error"),n=a.querySelector("button[type=submit]");t.textContent="",n.disabled=!0;try{const e=await API.applyReseller({name:a.elements.namedItem("name").value.trim(),slug:a.elements.namedItem("slug").value.trim().toLowerCase()});showToast(e.message,"success"),this.jt?.("reseller_apply",{label:e.tenant?.slug||""}),await this.renderResellerAccount()}catch(e){t.textContent=e.message,n.disabled=!1}},rpBind(e){e.querySelectorAll("[data-rp-auth]").forEach(e=>e.addEventListener("click",()=>{try{sessionStorage.setItem("girisSonrasiAdres","/bayilik")}catch{}this.showAuthPage("register"===e.dataset.rpAuth?"register":"login")}))}});